# nrpy/infrastructures/Dendro/Dendro_README_md.py
"""
Emit the generated project's README files.

Two documents: one for the project root and one for the solver directory that
is copied into a Dendro-GR checkout.

Author: Zachariah B. Etienne
        zachetie **at** gmail **dot* com
"""

BANNER = (
    "GENERATED FILE - DO NOT EDIT.\n"
    "AUTOMATICALLY GENERATED BY nrpy.infrastructures.Dendro.Dendro_README_md\n"
)


def output_project_README_md(
    project_name: str, solver_name: str, generator_module: str
) -> str:
    """
    Emit the generated project's top-level README.

    :param project_name: Name of the generated project directory.
    :param solver_name: Solver directory name, e.g. Dendro's own ``BSSN_GR``.
    :param generator_module: Dotted module name of the example that generated
        the project.
    :return: The README text.

    Doctests:
    >>> readme = output_project_README_md("dendro_fccz4", "BSSN_GR", "nrpy.examples.x")
    >>> readme.splitlines()[0]
    '# dendro_fccz4 — NRPy-generated solver for Dendro-GR'
    >>> "cmake -S Dendro-GR/BSSN_GR -B build" in readme
    True
    >>> "Regenerate with: `python -m nrpy.examples.x ...`" in readme
    True
    """
    return f"""# {project_name} — NRPy-generated solver for Dendro-GR

{BANNER}
Regenerate with: `python -m {generator_module} ...`

## Layout

- `Dendro-GR/{solver_name}/` — the sibling solver copied into a Dendro-GR
  checkout: generated sources, host context, parameter files, self-tests.

## Build and run the self-tests

    cmake -S Dendro-GR/{solver_name} -B build
    cmake --build build
    ctest --test-dir build

## Status

Dendrolib is UNPINNED in this repository, so the generated solver builds and
runs against the mock host stubs in `host_mock/dendro_mock.h`.  Real
Dendro-GR host integration, physical boundaries and the checkpoint ABI remain
separate qualified profiles.
"""


def output_solver_README_md(solver_name: str, generator_module: str) -> str:
    """
    Emit the generated solver directory's README.

    :param solver_name: Solver directory name, e.g. Dendro's own ``BSSN_GR``.
    :param generator_module: Dotted module name of the example that generated
        the project.
    :return: The README text.
    """
    return f"""# {solver_name} — NRPy-generated solver for Dendro-GR

{BANNER}
Regenerate with: `python -m {generator_module} ...`

## What this solver contains

- `generated/` — every file is emitted from the NRPy registries (gridfunction
  registry, CodeParameter registry, CFunction registry): state header,
  parameter struct, constants, per-CFunction sources, and the CMake source
  list.
- `include/`, `src/` — the mock-vehicle host context and the entry point.
- `pars/` — the generated sample parameter file.
- `tests/` — self-tests over the state registry, parameter registry, padding,
  memory offsets, upwind selection, RHS, initial data, exact-name selection,
  algebraic projection, and constraint diagnostics.

No formulation content is authored here: the names, order, stencils, and
expressions come from the NRPy registries, and the Dendro runtime owns only
lifecycle, mesh, and execution.

## Deferred, recorded rather than dropped

- This solver refuses to configure inside a Dendro-GR tree that defines a real
  `dendro5` target: its generated sources are compiled against the mock host
  types, so linking them to the real host would be a silent type mismatch.
- Real Dendro-GR host integration (CRTP context, `ot::DVector`/`ts::Ctx`
  lifecycle, remesh, checkpoint, output) lands after the pinned Dendrolib
  capability gates; see `dendrolib_pin.json` and
  `dendrolib_capabilities.json` in the NRPy Dendro infrastructure.
- Physical boundaries and the checkpoint ABI are separate qualified profiles.
"""


if __name__ == "__main__":
    import doctest
    import sys

    results = doctest.testmod()
    if results.failed > 0:
        print(f"Doctest failed: {results.failed} of {results.attempted} test(s)")
        sys.exit(1)
    print(f"Doctest passed: All {results.attempted} test(s) passed")
